//! `openapi.json`, the contract, read into what the checks need.
//!
//! The document is the one the Java control plane serves — `vectispire-angular/openapi.json`,
//! regenerated by `ClientContractSpecTest` — **as of the 0.11.1 line**, which is the line the port
//! targets. It is embedded rather than read from the repository: a check that could be pointed at
//! another file would pass by being pointed there. `reference/refresh.sh` moves it, by hand and in a
//! commit that says why.

use std::collections::{BTreeMap, BTreeSet};

use serde_json::Value;

/// The document the port is held to.
const EMBEDDED: &str = include_str!("../reference/openapi.json");

/// Where a parameter travels.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum In {
    Path,
    Query,
    Header,
    Cookie,
}

impl In {
    fn of(name: &str) -> Option<In> {
        match name {
            "path" => Some(In::Path),
            "query" => Some(In::Query),
            "header" => Some(In::Header),
            "cookie" => Some(In::Cookie),
            _ => None,
        }
    }
}

/// A parameter an operation declares.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Parameter {
    pub location: In,
    pub name: String,
    pub required: bool,
}

/// One operation: a method on a path.
#[derive(Clone, Debug)]
pub struct Operation {
    /// Upper case: `GET`, `POST`, …
    pub method: String,
    /// The template, as the document writes it: `/api/v1/projects/{projectId}`.
    pub path: String,
    pub operation_id: String,
    pub parameters: Vec<Parameter>,
    /// The security schemes this operation sets itself, `None` when it inherits the document's.
    pub security: Option<Vec<String>>,
    /// Whether the operation reads a body.
    pub has_request_body: bool,
    /// The media types of the request body, with their schemas.
    pub request: Vec<Media>,
    /// Declared responses by status: `"200"`, `"4XX"`, or `"default"`.
    pub responses: BTreeMap<String, Vec<Media>>,
}

/// A media type and the schema the document gives it (absent for a binary body).
#[derive(Clone, Debug)]
pub struct Media {
    pub media_type: String,
    pub schema: Option<Value>,
}

/// Why a document could not be read.
#[derive(Debug, thiserror::Error)]
pub enum DocumentError {
    #[error("openapi.json is not JSON: {0}")]
    NotJson(#[from] serde_json::Error),
    #[error("openapi.json is malformed: {0}")]
    Malformed(String),
}

/// The parsed contract.
#[derive(Debug)]
pub struct Document {
    operations: Vec<Operation>,
    /// `components`, kept whole: every `$ref` of a schema resolves inside it.
    components: Value,
    /// The schemes the document applies to every operation that does not set its own.
    default_security: Vec<String>,
    version: String,
}

impl Document {
    /// The embedded document.
    ///
    /// # Panics
    /// When the embedded file is not a document — a defect of the commit that changed it, which
    /// every test of this crate would show at once.
    #[must_use]
    pub fn embedded() -> Document {
        match Document::parse(EMBEDDED) {
            Ok(document) => document,
            Err(error) => panic!("the embedded openapi.json cannot be read: {error}"),
        }
    }

    /// Reads a document from its text.
    pub fn parse(text: &str) -> Result<Document, DocumentError> {
        let root: Value = serde_json::from_str(text)?;
        let malformed = |what: &str| DocumentError::Malformed(what.to_owned());
        let paths = root.get("paths").and_then(Value::as_object).ok_or_else(|| malformed("no `paths` object"))?;
        let components = root.get("components").cloned().unwrap_or(Value::Null);
        let default_security = schemes(root.get("security")).unwrap_or_default();
        let version = root
            .pointer("/info/version")
            .and_then(Value::as_str)
            .ok_or_else(|| malformed("no `info.version`"))?
            .to_owned();

        let mut operations = Vec::new();
        for (path, item) in paths {
            let item = item.as_object().ok_or_else(|| malformed("a path item is not an object"))?;
            for (method, operation) in item {
                if !is_method(method) {
                    continue;
                }
                operations.push(operation_of(&method.to_ascii_uppercase(), path, operation)?);
            }
        }
        Ok(Document { operations, components, default_security, version })
    }

    /// Every operation, in the document's path order then method order.
    #[must_use]
    pub fn operations(&self) -> &[Operation] {
        &self.operations
    }

    /// `components`: where a schema's `$ref` points.
    #[must_use]
    pub fn components(&self) -> &Value {
        &self.components
    }

    /// The security schemes an operation without its own inherits.
    #[must_use]
    pub fn default_security(&self) -> &[String] {
        &self.default_security
    }

    /// The `info.version` the document carries.
    #[must_use]
    pub fn version(&self) -> &str {
        &self.version
    }

    /// The operation of a method on exactly this template.
    #[must_use]
    pub fn operation(&self, method: &str, template: &str) -> Option<&Operation> {
        self.operations
            .iter()
            .find(|operation| operation.method.eq_ignore_ascii_case(method) && operation.path == template)
    }

    /// The operation a concrete request reaches: `GET /api/v1/projects/7` finds the template
    /// `/api/v1/projects/{projectId}`. A literal segment wins over a parameter, as a router's does.
    #[must_use]
    pub fn find(&self, method: &str, concrete: &str) -> Option<&Operation> {
        let wanted: Vec<&str> = concrete.trim_start_matches('/').split('/').collect();
        self.operations
            .iter()
            .filter(|operation| operation.method.eq_ignore_ascii_case(method))
            .filter_map(|operation| specificity(&operation.path, &wanted).map(|literals| (literals, operation)))
            .max_by_key(|(literals, _)| *literals)
            .map(|(_, operation)| operation)
    }

    /// The security schemes in force for an operation: its own, or the document's.
    #[must_use]
    pub fn effective_security<'a>(&'a self, operation: &'a Operation) -> &'a [String] {
        operation.security.as_deref().unwrap_or(&self.default_security)
    }

    /// The set of `(method, template)` the document lists.
    #[must_use]
    pub fn routes(&self) -> BTreeSet<(String, String)> {
        self.operations.iter().map(|operation| (operation.method.clone(), operation.path.clone())).collect()
    }
}

/// How specifically `template` matches `concrete`, when it matches at all: a literal segment counts
/// two, a parameter with a literal around it (`{token}.svg`) one, a bare parameter nothing.
fn specificity(template: &str, concrete: &[&str]) -> Option<usize> {
    let segments: Vec<&str> = template.trim_start_matches('/').split('/').collect();
    if segments.len() != concrete.len() {
        return None;
    }
    let mut score = 0;
    for (segment, actual) in segments.iter().zip(concrete) {
        match split_parameter(segment) {
            None if segment == actual => score += 2,
            None => return None,
            Some((prefix, _, suffix)) => {
                let fits = actual.len() > prefix.len() + suffix.len()
                    && actual.starts_with(prefix)
                    && actual.ends_with(suffix);
                if !fits {
                    return None;
                }
                score += usize::from(!prefix.is_empty() || !suffix.is_empty());
            }
        }
    }
    Some(score)
}

/// A segment with a parameter in it, as `(before, name, after)`: `{id}` is `("", "id", "")` and
/// `{token}.svg` is `("", "token", ".svg")`. `None` for a literal segment.
#[must_use]
pub fn split_parameter(segment: &str) -> Option<(&str, &str, &str)> {
    let open = segment.find('{')?;
    let close = open + segment[open..].find('}')?;
    Some((&segment[..open], &segment[open + 1..close], &segment[close + 1..]))
}

fn is_method(key: &str) -> bool {
    matches!(key, "get" | "put" | "post" | "delete" | "options" | "head" | "patch" | "trace")
}

fn schemes(security: Option<&Value>) -> Option<Vec<String>> {
    let requirements = security?.as_array()?;
    let mut names = BTreeSet::new();
    for requirement in requirements {
        if let Some(object) = requirement.as_object() {
            names.extend(object.keys().cloned());
        }
    }
    Some(names.into_iter().collect())
}

fn operation_of(method: &str, path: &str, operation: &Value) -> Result<Operation, DocumentError> {
    let malformed = |what: String| DocumentError::Malformed(format!("{method} {path}: {what}"));
    let operation_id = operation
        .get("operationId")
        .and_then(Value::as_str)
        .ok_or_else(|| malformed("no operationId".to_owned()))?
        .to_owned();

    let mut parameters = Vec::new();
    for parameter in operation.get("parameters").and_then(Value::as_array).into_iter().flatten() {
        let name = parameter
            .get("name")
            .and_then(Value::as_str)
            .ok_or_else(|| malformed("a parameter has no name".to_owned()))?;
        let place = parameter.get("in").and_then(Value::as_str).and_then(In::of);
        let Some(location) = place else {
            return Err(malformed(format!("parameter {name} is neither path, query, header nor cookie")));
        };
        let required = location == In::Path || parameter.get("required").and_then(Value::as_bool).unwrap_or(false);
        parameters.push(Parameter { location, name: name.to_owned(), required });
    }
    parameters.sort();

    let body = operation.get("requestBody");
    let request = body.map(media_of).unwrap_or_default();
    let mut responses = BTreeMap::new();
    if let Some(declared) = operation.get("responses").and_then(Value::as_object) {
        for (status, response) in declared {
            responses.insert(status.clone(), media_of(response));
        }
    }
    Ok(Operation {
        method: method.to_owned(),
        path: path.to_owned(),
        operation_id,
        parameters,
        security: schemes(operation.get("security")),
        has_request_body: body.is_some(),
        request,
        responses,
    })
}

fn media_of(holder: &Value) -> Vec<Media> {
    let Some(content) = holder.get("content").and_then(Value::as_object) else {
        return Vec::new();
    };
    content
        .iter()
        .map(|(media_type, media)| Media { media_type: media_type.clone(), schema: media.get("schema").cloned() })
        .collect()
}

/// The names between braces in a template, in order: `/a/{x}/b/{y}` gives `x`, `y`, and
/// `/badge/{token}.svg` gives `token`.
#[must_use]
pub fn path_parameters(template: &str) -> Vec<String> {
    template.split('/').filter_map(split_parameter).map(|(_, name, _)| name.to_owned()).collect()
}

/// `template` with every parameter replaced by `value`, keeping what surrounds it: a concrete path
/// that reaches the same route.
#[must_use]
pub fn fill_parameters(template: &str, value: &str) -> String {
    template
        .split('/')
        .map(|segment| match split_parameter(segment) {
            Some((prefix, _, suffix)) => format!("{prefix}{value}{suffix}"),
            None => segment.to_owned(),
        })
        .collect::<Vec<_>>()
        .join("/")
}
